<script>document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('student-psb-correction-form');form.addEventListener('submit',async event=>{event.preventDefault();const gross=form.elements.psb,discount=form.elements.potongan_psb_nominal;const amount=Number(gross.value.replace(/\./g,'')),cut=Number(discount.value.replace(/\./g,''));gross.setCustomValidity(Number.isInteger(amount)&&amount>0&&amount<=999999999999?'':'Isi Uang PSB positif maksimal 12 digit.');discount.setCustomValidity(Number.isInteger(cut)&&cut>=0&&cut<=amount?'':'Potongan PSB tidak boleh melebihi Uang PSB.');if(form.dataset.submitting==='1'||!form.reportValidity())return;form.dataset.submitting='1';const ok=await window.workflowConfirm({title:'Koreksi Pendaftaran ke PSB',message:'Tagihan awal SPP/Komite/DU dibatalkan. Riwayat audit tetap disimpan dan nominal PSB mengikuti yang Anda isi.',rows:[...<?= json_encode([$editStudent['NAMA'].' · '.$editStudent['NO_INDUK'],count($psbCorrection['bills']['tagihan_spp']).' tagihan SPP',count($psbCorrection['bills']['tagihan_komite']).' tagihan Komite',count($psbCorrection['bills']['tagihan_daftar_ulang']).' tagihan DU'],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>,'Uang PSB: Rp '+amount.toLocaleString('id-ID'),'Potongan: Rp '+cut.toLocaleString('id-ID'),'Total PSB: Rp '+(amount-cut).toLocaleString('id-ID'),'Alasan: '+form.elements.reason.value],action:'Simpan Koreksi'},event.submitter);if(!ok){delete form.dataset.submitting;return;}form.querySelector('button').disabled=true;HTMLFormElement.prototype.submit.call(form);});form.addEventListener('input',()=>{form.elements.psb.setCustomValidity('');form.elements.potongan_psb_nominal.setCustomValidity('');});});</script>
